  const horas = Math.floor(seconds / 3600)
  const minutos = Math.floor((seconds % 3600) / 60)
  const segundos = seconds % 60

  return [horas, minutos, segundos]
    .map((v) => String(v).padStart(2, '0'))
    .join(':')
}

