            <p>{contest.cantidadProblemas}</p>
          </div>

          <div className="space-y-1">
            <p className="font-semibold text-[var(--text-primary)]">
              Participantes
            </p>

            <p>{contest.cantidadParticipantes}</p>
          </div>
        </div>

        {/* <div className="flex flex-wrap items-center gap-3"> */}
