      aria-valuenow={safeValue}
      className={cn(
        'h-2 overflow-hidden rounded-full bg-[var(--surface-muted)]',
        className,
      )}
      {...props}
    >
      <div
        className="h-full bg-[var(--primary)]"
        style={{ width: `${safeValue}%` }}
      />
    </div>
