import type { EstadoTiempoConcurso, ModalidadConcurso } from '@/features/contests/types'

export type ContestUserAction =
  | 'JOIN_PUBLIC'
  | 'JOIN_PRIVATE'
  | 'VIEW_ACTIVE'
  | 'VIEW_FINISHED'
  | 'ENROLLED_UPCOMING'
  | 'REGISTRATION_CLOSED'
  | 'PRIVATE_FINISHED_REQUIRES_BACKEND'
  | 'UNKNOWN_BLOCKED'

export type ContestDetailMode = 'participation' | 'read-only' | 'blocked'

type AccessInput = {
  estadoTiempo: EstadoTiempoConcurso | string
  modalidad: ModalidadConcurso | string
  yaInscrito?: boolean
}

const normalized = (value: string) => value.trim().toLocaleLowerCase()

export const getContestUserAction = ({
  estadoTiempo,
  modalidad,
  yaInscrito = false,
}: AccessInput): ContestUserAction => {
  const state = normalized(estadoTiempo)
  const isPrivate = normalized(modalidad) === 'privado'

  if (state === 'proximo' || state === 'próximo') {
    if (yaInscrito) return 'ENROLLED_UPCOMING'
    return isPrivate ? 'JOIN_PRIVATE' : 'JOIN_PUBLIC'
  }
  if (state === 'activo' || state === 'en curso')
    return yaInscrito ? 'VIEW_ACTIVE' : 'REGISTRATION_CLOSED'
  if (state === 'finalizado') {
    if (yaInscrito || !isPrivate) return 'VIEW_FINISHED'
    return 'PRIVATE_FINISHED_REQUIRES_BACKEND'
  }
  return 'UNKNOWN_BLOCKED'
}

export const getContestDetailMode = (input: AccessInput) => {
  const action = getContestUserAction(input)
  if (action === 'VIEW_ACTIVE')
    return { mode: 'participation' as const, reason: undefined }
  if (action === 'VIEW_FINISHED')
    return { mode: 'read-only' as const, reason: 'El concurso finalizó; solo podés consultar su contenido.' }
  if (action === 'PRIVATE_FINISHED_REQUIRES_BACKEND')
    return {
      mode: 'blocked' as const,
      reason: 'Este concurso privado finalizado requiere una validación de consulta del backend.',
    }
  return { mode: 'blocked' as const, reason: 'No tenés acceso al detalle de este concurso.' }
}

import { useEffect, useRef, useState } from 'react'
import { Alert, Button } from '@/components/common'

type JoinContestModalProps = {
  contest: { codigo: string; nombre: string }
  privateContest: boolean
  pending: boolean
  error?: string
  onConfirm: (password: string | null) => Promise<void>
  onCancel: () => void
}

export function JoinContestModal({
  contest,
  privateContest,
  pending,
  error,
  onConfirm,
  onCancel,
}: JoinContestModalProps) {
  const [password, setPassword] = useState('')
  const [validationError, setValidationError] = useState('')
  const cancelRef = useRef<HTMLButtonElement>(null)

  useEffect(() => {
    cancelRef.current?.focus()
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape' && !pending) onCancel()
    }
    window.addEventListener('keydown', onKeyDown)
    return () => window.removeEventListener('keydown', onKeyDown)
  }, [onCancel, pending])

  const close = () => {
    if (pending) return
    setPassword('')
    setValidationError('')
    onCancel()
  }

  const submit = async (event: React.FormEvent) => {
    event.preventDefault()
    if (privateContest && !password) {
      setValidationError('Ingresá la contraseña del concurso.')
      return
    }
    setValidationError('')
    await onConfirm(privateContest ? password : null)
    setPassword('')
  }

  return (
    <div className="fixed inset-0 z-50 grid place-items-center bg-black/40 p-4" role="presentation">
      <section aria-modal="true" aria-labelledby="join-contest-title" role="dialog" className="w-full max-w-md rounded-lg bg-white p-6 shadow-xl">
        <h2 id="join-contest-title" className="text-lg font-bold">Inscribirse al concurso</h2>
        <p className="mt-2 text-sm text-[var(--text-secondary)]">
          Confirmá tu inscripción a {contest.nombre} ({contest.codigo}).
        </p>
        <form className="mt-5 space-y-4" onSubmit={submit} aria-busy={pending}>
          {privateContest && (
            <label className="block text-sm font-semibold" htmlFor="contest-password">
              Contraseña del concurso
              <input id="contest-password" type="password" autoComplete="off" value={password} onChange={(event) => setPassword(event.target.value)} className="mt-1 w-full rounded-md border border-[var(--border)] px-3 py-2" aria-describedby={validationError || error ? 'join-password-error' : undefined} />
            </label>
          )}
          {(validationError || error) && <Alert id="join-password-error" tone="danger">{validationError || error}</Alert>}
          <div className="flex justify-end gap-3">
            <Button ref={cancelRef} type="button" variant="outline" onClick={close} disabled={pending}>Cancelar</Button>
            <Button type="submit" loading={pending}>Confirmar inscripción</Button>
          </div>
        </form>
      </section>
    </div>
  )
}

